/**
 * CODE GIFTZ — W5 security & credential E2E (isolated :3100 instance).
 *
 * Phases (run against the ISOLATED verify.db only — never the production DB):
 *  nocred — server WITHOUT BEAN_CREDENTIALS_MASTER_KEY: credential features
 *           must FAIL CLOSED with a typed error; /api/v1/models reports
 *           credentialEncryption:"not-configured".
 *  cred   — server WITH a disposable master key (generated by the caller,
 *           never printed): create a disposable credential, prove the
 *           plaintext never reaches the API surface or the DB file at rest,
 *           rotate the master-key envelope, then exercise the application
 *           API key lifecycle (create → use → scope-deny → invalid → rotate
 *           (old dies) → revoke → double-revoke 422) + hash-only storage +
 *           per-principal 30/min rate limit (upstream-free burst).
 *
 * Honesty rules: no real provider secrets are used; the disposable secret and
 * master key are generated at run time and NEVER printed, logged or saved.
 * Every assertion prints PASS/FAIL with evidence (status codes, codes,
 * boolean presence checks) — the script exits non-zero on any failure.
 */
import { Database } from 'bun:sqlite'

const BASE = (process.argv[2] ?? 'http://127.0.0.1:3100').replace(/\/$/, '')
const PHASE = process.argv[3] ?? ''
const DB_PATH = '/home/z/my-project/scripts/giftz-verify-out/verify.db'

let failures = 0
function check(name: string, passed: boolean, detail = ''): void {
  console.log(`  [${passed ? 'PASS' : 'FAIL'}] ${name}${detail ? ` — ${detail}` : ''}`)
  if (!passed) failures += 1
}

/** Disposable secrets generated in-process — never printed anywhere. */
const DISPOSABLE_SECRET = `sk-disposable-${crypto.randomUUID().replace(/-/g, '')}`
const DISPOSABLE_SECRET_2 = `sk-disposable-${crypto.randomUUID().replace(/-/g, '')}`

async function api(path: string, init: RequestInit & { cookie?: string } = {}): Promise<Response> {
  const headers: Record<string, string> = { 'content-type': 'application/json', ...(init.cookie ? { cookie: init.cookie } : {}) }
  if (init.headers) Object.assign(headers, init.headers)
  return fetch(`${BASE}${path}`, { ...init, headers })
}

/** Promote a freshly registered user to admin in the ISOLATED DB, then log in. */
async function adminCookie(): Promise<string> {
  const email = `giftz-sec-${Date.now()}@bean-eval.dev`
  const password = 'SecE2eOnly2026x'
  const reg = await api('/api/auth/register', { method: 'POST', body: JSON.stringify({ email, password, name: 'SEC E2E Admin' }) })
  if (!reg.ok) throw new Error(`register failed: ${reg.status} ${await reg.text().catch(() => '')}`)
  const db = new Database(DB_PATH)
  db.run(`UPDATE User SET role='admin' WHERE email=?`, [email])
  const role = db.query(`SELECT role FROM User WHERE email=?`).get(email) as { role: string } | null
  db.close()
  if (role?.role !== 'admin') throw new Error('role promotion failed')
  const login = await api('/api/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) })
  if (!login.ok) throw new Error(`login failed: ${login.status}`)
  const cookie = login.headers.getSetCookie().map((c) => c.split(';')[0]).join('; ')
  if (!cookie) throw new Error('no session cookie')
  return cookie
}

function dbScanForPlaintext(needles: string[]): { fileHits: string[]; keyHashShapeOk: boolean; keyRows: number } {
  const db = new Database(DB_PATH, { readonly: true })
  const credRows = db.query(`SELECT encrypted, maskedHint, status FROM ProviderCredential`).all() as Array<{ encrypted: string; maskedHint: string; status: string }>
  const keyRows = db.query(`SELECT prefix, keyHash, status FROM ApiKey`).all() as Array<{ prefix: string; keyHash: string; status: string }>
  db.close()
  const blob = Buffer.concat([
    Buffer.from(credRows.map((r) => `${r.encrypted}\u0000${r.maskedHint}`).join('\u0000')),
    Buffer.from(keyRows.map((r) => `${r.prefix}\u0000${r.keyHash}`).join('\u0000')),
  ]).toString('binary')
  const fileHits = needles.filter((n) => blob.includes(n))
  const keyHashShapeOk = keyRows.every((r) => /^[a-f0-9]{64}$/.test(r.keyHash) && r.prefix.startsWith('bgk_'))
  return { fileHits, keyHashShapeOk, keyRows: keyRows.length }
}

async function phaseNocred(): Promise<void> {
  console.log(`\n== PHASE nocred (server without BEAN_CREDENTIALS_MASTER_KEY) ==`)
  const cookie = await adminCookie()
  const create = await api('/api/admin/gateway', {
    method: 'POST', cookie,
    body: JSON.stringify({ action: 'create-credential', provider: 'openai-compatible', label: 'disposable-e2e', apiKey: DISPOSABLE_SECRET }),
  })
  const body = (await create.json().catch(() => ({}))) as Record<string, unknown>
  const errCode = String((body.error as Record<string, unknown> | undefined)?.code ?? '')
  check('credential create fails closed without master key (503 PRODUCT_UNAVAILABLE)', create.status === 503 && errCode === 'PRODUCT_UNAVAILABLE', `HTTP ${create.status} code=${errCode}`)
  check('typed message names the missing configuration', JSON.stringify(body).includes('BEAN_CREDENTIALS_MASTER_KEY') && !JSON.stringify(body).includes(DISPOSABLE_SECRET))
  const models = await api('/api/v1/models', { headers: { authorization: 'Bearer bgk_irrelevant' } })
  check('models endpoint reachable (auth section separate from credential config)', models.status === 401 || models.status === 200, `HTTP ${models.status}`)
}

async function phaseCred(): Promise<void> {
  console.log(`\n== PHASE cred (server WITH disposable master key) ==`)
  const cookie = await adminCookie()

  // -- credential lifecycle --
  const create = await api('/api/admin/gateway', {
    method: 'POST', cookie,
    body: JSON.stringify({ action: 'create-credential', provider: 'openai-compatible', label: 'disposable-e2e', apiKey: DISPOSABLE_SECRET }),
  })
  const created = (await create.json().catch(() => ({}))) as Record<string, unknown>
  check('credential created (admin session)', create.ok, `HTTP ${create.status}`)
  const credText = JSON.stringify(created)
  check('create response exposes NO plaintext secret', !credText.includes(DISPOSABLE_SECRET))
  check('create response exposes only masked hint/status', credText.includes('maskedHint') || credText.includes('••') || credText.includes('sk-••••'), 'masked hint present')
  const credId = (created.credential as Record<string, unknown> | undefined)?.id as string ?? (created.id as string | undefined) ?? ((created.data as Record<string, unknown> | undefined)?.id as string | undefined)
  check('credential id returned for lifecycle calls', typeof credId === 'string' && credId.length > 0, `id=${credId ? String(credId).slice(0, 8) + '…' : 'MISSING'}`)

  const list = await api('/api/admin/gateway', { cookie })
  const listed = (await list.json().catch(() => ({}))) as Record<string, unknown>
  const listText = JSON.stringify(listed)
  const fullLeak = listText.includes(DISPOSABLE_SECRET)
  const prefixLeak = listText.includes(DISPOSABLE_SECRET.slice(0, 24))
  console.log(`      list debug: ok=${list.ok} status=${list.status} fullLeak=${fullLeak} prefix24Leak=${prefixLeak} bytes=${listText.length}`)
  check('GET /api/admin/gateway responds ok', list.ok && list.status === 200, `HTTP ${list.status}`)
  check('credential list exposes NO full plaintext', !fullLeak)
  check('credential list exposes no >24-char secret prefix', !prefixLeak)

  const scan1 = dbScanForPlaintext([DISPOSABLE_SECRET, DISPOSABLE_SECRET.slice(0, 32)])
  check('DB at rest contains NO plaintext credential (envelope only)', scan1.fileHits.length === 0, `hits=${scan1.fileHits.length}`)
  const db = new Database(DB_PATH, { readonly: true })
  const enc = (db.query(`SELECT encrypted FROM ProviderCredential LIMIT 1`).get() as { encrypted: string } | null)?.encrypted ?? ''
  db.close()
  check('stored envelope uses the versioned v1:<iv>.<tag>.<ct> format', /^v1:[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(enc), `envelope prefix=${enc.slice(0, 3)} len=${enc.length}`)

  const rotate = await api('/api/admin/gateway', { method: 'POST', cookie, body: JSON.stringify({ action: 'rotate-master-key' }) })
  const rotBody = (await rotate.json().catch(() => ({}))) as Record<string, unknown>
  const rotText = JSON.stringify(rotBody)
  check('rotate-master-key re-encrypts under the current env key', rotate.ok, `HTTP ${rotate.status} body=${rotText.slice(0, 160)}`)
  check('rotation reports counts, not secrets', !rotText.includes(DISPOSABLE_SECRET))
  const scan2 = dbScanForPlaintext([DISPOSABLE_SECRET])
  check('after rotation the plaintext is STILL absent at rest', scan2.fileHits.length === 0)

  // -- application API key lifecycle --
  const mk = await api('/api/v1/keys', {
    method: 'POST', cookie,
    body: JSON.stringify({ name: 'closure-e2e', permissions: ['chat:completions', 'models:read'], rateLimitPerMin: 60 }),
  })
  const mkBody = (await mk.json().catch(() => ({}))) as Record<string, unknown>
  const rawKey = String(mkBody.key ?? '')
  check('POST /api/v1/keys returns the raw key exactly once', mk.ok && rawKey.startsWith('bgk_') && rawKey.length >= 40, `prefix ok=${rawKey.startsWith('bgk_')}`)
  const mkId = String(mkBody.id ?? (mkBody.data as Record<string, unknown> | undefined)?.id ?? '')

  const listKeys = await api('/api/v1/keys', { cookie })
  const listKeysText = JSON.stringify(await listKeys.json().catch(() => ({})))
  check('GET /api/v1/keys shows metadata only (raw key never listed)', listKeys.ok && !listKeysText.includes(rawKey), `HTTP ${listKeys.status}`)

  const use = await api('/api/v1/models', { headers: { authorization: `Bearer ${rawKey}` } })
  const useBody = (await use.json().catch(() => ({}))) as Record<string, unknown>
  check('app key authenticates GET /api/v1/models', use.ok && useBody.ok === true, `HTTP ${use.status}`)
  const modelsData = (useBody.models as Array<Record<string, unknown>> | undefined) ?? []
  const ids = modelsData.map((m) => String(m.id))
  console.log(`      live catalogue ids: ${ids.join(', ')}`)
  check('catalogue includes gateway chat models', ids.includes('bean-chat-hosted') && ids.includes('bean-code-hosted'))
  const editLocal = modelsData.find((m) => String(m.id) === 'bean-image-edit-local')
  const editStatus = String(editLocal?.availability)
  check('bean-image-edit-local honestly non-operational (disabled/unavailable + reason)', editStatus === 'disabled' || editStatus === 'unavailable', `availability=${editStatus}`)
  const external = modelsData.find((m) => String(m.id) === 'bean-external-openai-compatible')
  check('bean-external-openai-compatible now honestly CONFIGURED (this phase created its credential)', !!external && external.configurationStatus === 'configured', `status=${String(external?.configurationStatus)}`)
  check('credentialEncryption reported configured', useBody.credentialEncryption === 'configured')

  // -- scope enforcement (models:read-only key must NOT pass chat) --
  const mk2 = await api('/api/v1/keys', {
    method: 'POST', cookie,
    body: JSON.stringify({ name: 'closure-e2e-readonly', permissions: ['models:read'], rateLimitPerMin: 60 }),
  })
  const mk2Body = (await mk2.json().catch(() => ({}))) as Record<string, unknown>
  const readonlyKey = String(mk2Body.key ?? '')
  check('second key created with models:read scope only', mk2.ok && readonlyKey.startsWith('bgk_'))
  const denied = await api('/api/v1/chat/completions', {
    method: 'POST', headers: { authorization: `Bearer ${readonlyKey}` },
    body: JSON.stringify({ model: 'bean-chat-hosted', messages: [{ role: 'user', content: 'hi' }] }),
  })
  const deniedBody = (await denied.json().catch(() => ({}))) as Record<string, unknown>
  const deniedCode = String((deniedBody.error as Record<string, unknown> | undefined)?.code ?? '')
  check('scope enforcement: chat denied for models:read-only key (403 FORBIDDEN)', denied.status === 403 && deniedCode === 'FORBIDDEN', `HTTP ${denied.status} code=${deniedCode}`)

  // -- invalid / unauthenticated --
  const bad = await api('/api/v1/models', { headers: { authorization: 'Bearer bgk_totallyinvalidkey0000000000000000000000000000000000' } })
  check('invalid key rejected 401 UNAUTHENTICATED', bad.status === 401, `HTTP ${bad.status}`)
  const none = await api('/api/v1/models')
  check('no principal rejected 401', none.status === 401, `HTTP ${none.status}`)

  // -- rotation: old key dies immediately --
  const rot = await api(`/api/v1/keys/${mkId}/rotate`, { method: 'POST', cookie })
  const rotKeyBody = (await rot.json().catch(() => ({}))) as Record<string, unknown>
  const newRaw = String(rotKeyBody.key ?? '')
  check('rotate returns a NEW raw key exactly once', rot.ok && newRaw.startsWith('bgk_') && newRaw !== rawKey)
  const oldUse = await api('/api/v1/models', { headers: { authorization: `Bearer ${rawKey}` } })
  check('OLD key rejected immediately after rotation', oldUse.status === 401, `HTTP ${oldUse.status}`)
  const newUse = await api('/api/v1/models', { headers: { authorization: `Bearer ${newRaw}` } })
  check('NEW key authenticates after rotation', newUse.ok, `HTTP ${newUse.status}`)

  // -- revocation --
  const del = await api(`/api/v1/keys/${mkId}`, { method: 'DELETE', cookie })
  check('DELETE /api/v1/keys/:id revokes', del.ok, `HTTP ${del.status}`)
  const revokedUse = await api('/api/v1/models', { headers: { authorization: `Bearer ${newRaw}` } })
  check('revoked key rejected (401/403)', revokedUse.status === 401 || revokedUse.status === 403, `HTTP ${revokedUse.status}`)
  const delAgain = await api(`/api/v1/keys/${mkId}`, { method: 'DELETE', cookie })
  const delAgainBody = (await delAgain.json().catch(() => ({}))) as Record<string, unknown>
  const delAgainCode = String((delAgainBody.error as Record<string, unknown> | undefined)?.code ?? '')
  check('double-revoke is a typed VALIDATION_ERROR (400)', delAgain.status === 400 && delAgainCode === 'VALIDATION_ERROR', `HTTP ${delAgain.status} code=${delAgainCode}`)

  // -- hash-only storage --
  const scan3 = dbScanForPlaintext([rawKey, newRaw, readonlyKey])
  check('raw app keys NEVER stored in DB (hash-only)', scan3.fileHits.length === 0 && scan3.keyHashShapeOk, `hits=${scan3.fileHits.length} hashShapeOk=${scan3.keyHashShapeOk} keyRows=${scan3.keyRows}`)

  // -- per-principal 30/min rate limit (upstream-free burst: chat-scoped key + unknown model — planGatewayChat rejects before any provider contact) --
  const mk3 = await api('/api/v1/keys', {
    method: 'POST', cookie,
    body: JSON.stringify({ name: 'closure-e2e-burst', permissions: ['chat:completions'], rateLimitPerMin: 60 }),
  })
  const burstKey = String(((await mk3.json().catch(() => ({}))) as Record<string, unknown>).key ?? '')
  check('burst key created with chat:completions scope', mk3.ok && burstKey.startsWith('bgk_'))
  let sawRejection = 0
  let saw429 = -1
  let throttleCode = ''
  const statuses: number[] = []
  for (let i = 1; i <= 40; i++) {
    const r = await api('/api/v1/chat/completions', {
      method: 'POST', headers: { authorization: `Bearer ${burstKey}` },
      body: JSON.stringify({ model: 'bean-nonexistent-model', messages: [{ role: 'user', content: 'hi' }] }),
    })
    statuses.push(r.status)
    if (r.status === 429) {
      saw429 = i
      const eb = (await r.json().catch(() => ({}))) as Record<string, unknown>
      throttleCode = String((eb.error as Record<string, unknown> | undefined)?.code ?? '')
      break
    }
  }
  console.log(`      burst statuses: ${statuses.join(',')}`)
  const preThrottle = statuses.slice(0, saw429 > 0 ? saw429 - 1 : statuses.length)
  sawRejection = preThrottle.filter((s) => [400, 404, 422, 503].includes(s)).length
  check('caller rate limit engaged within the 30/min window', saw429 > 0 && saw429 <= 35, `throttled at request #${saw429}`)
  check('pre-throttle requests were honest unknown-model rejections (no upstream contact)', sawRejection >= Math.min(30, saw429 - 1), `pre-throttle rejections=${sawRejection}`)
  check('429 carries the stable RATE_LIMITED code', throttleCode === 'RATE_LIMITED', `code=${throttleCode}`)
}

const phase = PHASE
if (phase === 'nocred') await phaseNocred()
else if (phase === 'cred') await phaseCred()
else {
  console.error('unknown phase — use nocred | cred')
  process.exit(3)
}
console.log(failures === 0 ? `\nPHASE ${phase}: ALL CHECKS PASS` : `\nPHASE ${phase}: ${failures} FAILURE(S)`)
process.exit(failures === 0 ? 0 : 1)
